# Standalone concomitant-medications analysis generated from DOCX code segment.

suppressPackageStartupMessages({library(dplyr);library(tidyr)})
set.seed(20260828)
arg<-grep("^--file=",commandArgs(FALSE),value=TRUE);raw_path<-if(length(arg))sub("^--file=","",arg[1])else".";script_path<-normalizePath(gsub("~\\+~"," ",raw_path));out_dir<-if(file.info(script_path)$isdir)script_path else dirname(script_path);stem<-tools::file_path_sans_ext(basename(script_path))
unpack<-function(s)read.csv(text=rawToChar(memDecompress(base64enc::base64decode(s),type="gzip")),stringsAsFactors=FALSE,check.names=FALSE,na.strings=c("NA", ""))
xml<-function(x){x[is.na(x)]<-"";x<-gsub("&","&amp;",x,fixed=TRUE);x<-gsub("<","&lt;",x,fixed=TRUE);x<-gsub(">","&gt;",x,fixed=TRUE);gsub('"',"&quot;",x,fixed=TRUE)}
colx<-function(n){z<-character(length(n));for(j in seq_along(n)){k<-n[j];s<-"";while(k>0){k<-k-1;s<-paste0(intToUtf8(65+k%%26),s);k<-k%/%26};z[j]<-s};z}
write_xlsx<-function(sheets,path){sheets<-lapply(sheets,function(d){names(d)<-toupper(names(d));d});sn<-names(sheets);td<-tempfile('x');dir.create(td);for(z in c('_rels','docProps','xl','xl/_rels','xl/worksheets'))dir.create(file.path(td,z),recursive=TRUE,showWarnings=FALSE);writeLines(paste0('<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>',paste0('<Override PartName="/xl/worksheets/sheet',seq_along(sheets),'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>',collapse=''),'</Types>'),file.path(td,'[Content_Types].xml'));writeLines('<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',file.path(td,'_rels/.rels'));writeLines(paste0('<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>',paste0('<sheet name="',sn,'" sheetId="',seq_along(sn),'" r:id="rId',seq_along(sn),'"/>',collapse=''),'</sheets></workbook>'),file.path(td,'xl/workbook.xml'));writeLines(paste0('<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">',paste0('<Relationship Id="rId',seq_along(sn),'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet',seq_along(sn),'.xml"/>',collapse=''),'<Relationship Id="rId',length(sn)+1,'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'),file.path(td,'xl/_rels/workbook.xml.rels'));writeLines('<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="10"/><name val="Arial"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="10"/><name val="Arial"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF1F4E78"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf xfId="0"/><xf xfId="0" fontId="1" fillId="1"/></cellXfs></styleSheet>',file.path(td,'xl/styles.xml'));for(k in seq_along(sheets)){d<-sheets[[k]];a<-rbind(names(d),as.matrix(d));rs<-vapply(seq_len(nrow(a)),function(i){cs<-vapply(seq_len(ncol(a)),function(j){v<-as.character(a[i,j]);if(i>1&&is.numeric(d[[j]])&&!is.na(d[i-1,j]))sprintf('<c r="%s%d"><v>%s</v></c>',colx(j),i,d[i-1,j])else sprintf('<c r="%s%d" t="inlineStr" s="%d"><is><t>%s</t></is></c>',colx(j),i,ifelse(i==1,1,0),xml(v))},character(1));sprintf('<row r="%d">%s</row>',i,paste0(cs,collapse=''))},character(1));writeLines(paste0('<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><sheetData>',paste0(rs,collapse=''),'</sheetData></worksheet>'),file.path(td,'xl/worksheets',paste0('sheet',k,'.xml')))};old<-setwd(td);on.exit(setwd(old),add=TRUE);if(file.exists(path))unlink(path);utils::zip(path,list.files('.',recursive=TRUE,all.files=TRUE,no..=TRUE),flags='-q')}
esc<-function(x){x<-gsub('\\\\','\\\\\\\\',as.character(x));gsub('([{}])','\\\\\\1',x)}
write_rtf<-function(tab,title,path,note){tab<-as.data.frame(tab,check.names=FALSE);tab[]<-lapply(tab,as.character);con<-file(path,'wb');on.exit(close(con));w<-function(...)writeLines(paste0(...),con,useBytes=TRUE);w('{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Arial;}}\\landscape\\paperw15840\\paperh12240\\margl600\\margr600\\margt500\\margb600');w('\\pard\\f0\\fs15 PILOT\\tab Confidential\\tab Page {\\field{\\*\\fldinst PAGE}} of {\\field{\\*\\fldinst NUMPAGES}}\\par');w('\\pard\\qc\\b\\fs19 ',esc(title),'\\b0\\par\\pard\\qc\\fs15 Safety Population\\par\\par');n<-ncol(tab);ends<-cumsum(c(6000,rep(8640/(n-1),n-1)));for(i in 0:nrow(tab)){v<-if(i==0)names(tab)else unlist(tab[i,],use.names=FALSE);bd<-if(i==0)'\\clbrdrt\\brdrs\\brdrw15\\clbrdrb\\brdrs\\brdrw15'else if(i==nrow(tab))'\\clbrdrb\\brdrs\\brdrw15'else'';w('\\trowd\\trgaph60',if(i==0)'\\trhdr'else'',paste0(bd,'\\cellx',round(ends),collapse=''));for(j in seq_len(n))w('\\intbl',if(j==1)'\\ql'else'\\qc',if(i==0)'\\b'else'\\b0','\\f0\\fs13 ',esc(v[j]),'\\cell');w('\\row')};w('\\pard\\ql\\fs12\\par ',esc(note),'\\par Source: simulated data generated by this standalone program. Generated: ',format(Sys.Date(),'%d%b%Y'),'\\par}')}
simulate<-function(a,c){outa<-list();outc<-list();idn<-1L;for(t in sort(unique(a$TRT01AN))){ids<-a$USUBJID[a$TRT01AN==t];for(old in sample(ids,2*length(ids),replace=TRUE)){id<-sprintf('PILOT-%04d',idn);idn<-idn+1L;outa[[length(outa)+1]]<-data.frame(USUBJID=id,TRT01AN=t,SAFFL='Y');x<-c[c$USUBJID==old,,drop=FALSE];if(nrow(x)){x$USUBJID<-id;outc[[length(outc)+1]]<-x}}};list(ADSL=bind_rows(outa),ADCM=bind_rows(outc))}
fmt<-function(n,d)ifelse(n==0,'0',sprintf('%d (%.1f%%)',n,100*n/d))

EMBED_ADSL<-"H4sIAG2vkWoC/42SzQrCMBCE7z5LhMwmqXqsSKGlqNj04Pu/iDYRDbOhNsePmf2ZzTzN56G/mPiIFu3VTG3Xjbt7P97iHvb9YMQ8P8AtwBt8ga8qFHBrlgSkAMcMfhbhGvUuwoqGFBAGXBS+UEjusjLHAmC1hUBlF1I0hSJwyAmEwoLqtipTaAsBx8AzCBvyUG3BtyVQRnjgwSS3xZ/bql94SjVegA6VGs8CAAA="
EMBED_ADCM<-""
ORIGINAL_N<-41L

make_out<-function(a,c){den<-a%>%count(TRT01AN,name='D');labs<-setNames(paste0(ifelse(den$TRT01AN==1,'Placebo','Active'),' (N=',den$D,')'),den$TRT01AN);labs<-c(labs,Total=paste0('Total (N=',sum(den$D),')'));x<-bind_rows(c%>%mutate(TREATMENT=as.character(TRT01AN)),c%>%mutate(TREATMENT='Total'));get<-function(z,keys){z%>%group_by(across(all_of(c(keys,'TREATMENT'))))%>%summarise(N=n_distinct(USUBJID),.groups='drop')};overall<-x%>%group_by(TREATMENT)%>%summarise(N=n_distinct(USUBJID),.groups='drop')%>%mutate(ORDER=0,K2='',K4='',KPT='',LABEL='Overall');l2<-get(x,'CM2ATCL')%>%mutate(ORDER=1,K2=CM2ATCL,K4='',KPT='',LABEL=CM2ATCL);l4<-get(x,c('CM2ATCL','CM4ATCL'))%>%mutate(ORDER=2,K2=CM2ATCL,K4=CM4ATCL,KPT='',LABEL=paste0('  ',CM4ATCL));pt<-get(x,c('CM2ATCL','CM4ATCL','CMDECOD'))%>%mutate(ORDER=3,K2=CM2ATCL,K4=CM4ATCL,KPT=CMDECOD,LABEL=paste0('    ',CMDECOD));z<-bind_rows(overall,l2,l4,pt)%>%left_join(bind_rows(den%>%transmute(TREATMENT=as.character(TRT01AN),D),data.frame(TREATMENT='Total',D=sum(den$D))),by='TREATMENT')%>%mutate(VALUE=fmt(N,D))%>%select(ORDER,K2,K4,KPT,LABEL,TREATMENT,VALUE)%>%pivot_wider(names_from=TREATMENT,values_from=VALUE,values_fill='0');names(z)[names(z)=='1']<-labs['1'];names(z)[names(z)=='2']<-labs['2'];names(z)[names(z)=='Total']<-labs['Total'];z%>%arrange(K2,K4,KPT,ORDER)%>%select(Concomitant.Medication=LABEL,all_of(unname(labs)))}
TITLE<-'Table 1. Concomitant Medications by ATC Classification and Preferred Term';NOTE<-'Values are number and percentage of subjects. A subject is counted once within each category.'

adsl<-unpack(EMBED_ADSL);adcm<-unpack(EMBED_ADCM);sim<-simulate(adsl,adcm);names(sim$ADSL)<-toupper(names(sim$ADSL));names(sim$ADCM)<-toupper(names(sim$ADCM));stopifnot(n_distinct(sim$ADSL$USUBJID)==2*ORIGINAL_N);write_xlsx(sim,file.path(out_dir,paste0(stem,'_simulated_data.xlsx')));output<-make_out(sim$ADSL,sim$ADCM);write_rtf(output,TITLE,file.path(out_dir,paste0(stem,'.rtf')),NOTE);message(sprintf('Created %s: original N=%d; simulated N=%d',stem,ORIGINAL_N,n_distinct(sim$ADSL$USUBJID)))
